import{_ as s,C as n,o,c as i,j as a,a as r,G as l,a3 as d}from"./chunks/framework.exbasbhr.js";const f=JSON.parse('{"title":"Files & Data Locations","description":"Where ICC-CE keeps settings, saved ink, logs and crash reports","frontmatter":{"title":"Files & Data Locations","description":"Where ICC-CE keeps settings, saved ink, logs and crash reports"},"headers":[],"relativePath":"en/guide/files-and-data.md","filePath":"en/guide/files-and-data.md"}'),p={name:"en/guide/files-and-data.md"};function c(h,e,u,g,m,b){const t=n("ArticleMetadata");return o(),i("div",null,[e[0]||(e[0]=a("h1",{id:"files-data-locations",tabindex:"-1"},[r("Files & Data Locations "),a("a",{class:"header-anchor",href:"#files-data-locations","aria-label":'Permalink to "Files & Data Locations"'},"​")],-1)),l(t),e[1]||(e[1]=d(`<h2 id="directory-layout" tabindex="-1">Directory layout <a class="header-anchor" href="#directory-layout" aria-label="Permalink to &quot;Directory layout&quot;">​</a></h2><p>ICC-CE keeps user data together in its data directory:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data directory/</span></span>
<span class="line"><span>├── Settings.json          User settings (toolbar, gestures, everything)</span></span>
<span class="line"><span>├── Saves/                 Auto-saved ink</span></span>
<span class="line"><span>│   └── &lt;presentation&gt;/     One folder per presentation</span></span>
<span class="line"><span>├── Logs/                  Runtime logs</span></span>
<span class="line"><span>└── CrashLogs/             Crash reports</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">Finding it quickly</p><p>For portable builds the data directory usually lives inside the program folder; for installed builds it sits under your user profile&#39;s application data folder. The most reliable way is to look for an &quot;open data folder&quot; entry in the settings UI.</p></div><h2 id="settings-json" tabindex="-1">Settings.json <a class="header-anchor" href="#settings-json" aria-label="Permalink to &quot;Settings.json&quot;">​</a></h2><p>Every setting is serialised into this single JSON file, grouped by area (canvas, gestures, shape recognition, PowerPoint, appearance, startup, advanced, automation, security and so on).</p><p><strong>If you edit it by hand:</strong></p><ul><li>Exit ICC-CE completely first, otherwise it will overwrite your changes with its in-memory state on exit</li><li>Keep the file UTF-8 encoded</li><li>Keys are case-sensitive; a mistyped key is ignored silently rather than reported</li><li>If you break it, just delete the file — a fresh default config is generated on next start</li></ul><h2 id="saved-ink" tabindex="-1">Saved ink <a class="header-anchor" href="#saved-ink" aria-label="Permalink to &quot;Saved ink&quot;">​</a></h2><p>Auto-saved ink is written to <code>Saves</code>. The location is controlled by the automation settings and can point to a network share or USB drive.</p><div class="warning custom-block"><p class="custom-block-title">Path changes</p><p>Older documentation mentioned different save paths; everything is now unified under <code>Saves</code>. When upgrading from an old version, archives in the old folder are not migrated automatically — copy them over yourself.</p></div><h2 id="logs-and-crash-reports" tabindex="-1">Logs and crash reports <a class="header-anchor" href="#logs-and-crash-reports" aria-label="Permalink to &quot;Logs and crash reports&quot;">​</a></h2><ul><li><strong>Logs</strong>: startup, integration and recognition activity — the first place to look when something breaks</li><li><strong>CrashLogs</strong>: generated when the app terminates abnormally, including the call stack</li></ul><p>When reporting a bug, please attach the files matching the time the problem occurred; it speeds up diagnosis a lot. Logs may contain presentation file names, so feel free to redact them before sending.</p><h2 id="backup-and-mass-deployment" tabindex="-1">Backup and mass deployment <a class="header-anchor" href="#backup-and-mass-deployment" aria-label="Permalink to &quot;Backup and mass deployment&quot;">​</a></h2><p><strong>Backup</strong>: copy <code>Settings.json</code> and the <code>Saves</code> folder.</p><p><strong>Mass deployment</strong>: configure one machine, then distribute its <code>Settings.json</code> to the same location on the others to give every device the same toolbar layout and behaviour. Combined with the portable build, you can simply copy the whole folder.</p><div class="warning custom-block"><p class="custom-block-title">Lab environments</p><p>Some labs use restore cards or make the install directory read-only. In that case point the data directory at a partition that is not reset, otherwise settings and ink are lost on every reboot.</p></div>`,18))])}const v=s(p,[["render",c]]);export{f as __pageData,v as default};
